from collections import Counter

def transform(g):
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]
    for i in range(h):
        for j in range(w):
            c = Counter(g[y][x] for y in range(max(0, i-1), min(h, i+2))
                        for x in range(max(0, j-1), min(w, j+2))
                        if (y, x) != (i, j))
            if c:
                color, n = c.most_common(1)[0]
                if n >= 5:
                    out[i][j] = color
                elif g[i][j] in (0, 1, 4, 5, 6, 7, 8, 9) and n >= 4:
                    out[i][j] = color
    return out
